class CashierPOS:
    def __init__(self):
        self.items = []  # 记录商品列表
        self.state = 'closed'  # 初始化状态为关闭

    def open(self):
        self.state = 'open'  # 打开POS

    def close(self):
        self.state = 'closed'  # 关闭POS

    def add_item(self, item, price):
        self.items.append({'item': item, 'price': price})  # 添加商品到列表

    def remove_item(self, item):
        for item_info in self.items:
            if item_info['item'] == item:
                self.items.remove(item_info)  # 移除相匹配的商品

    def check_balance(self):
        if self.state == 'open':
            total = sum(item['price'] for item in self.items)
            return f'Current balance: ${total}'
        else:
            return 'Cannot check balance, POS is closed.'

    def print_receipt(self):
        if self.state == 'open':
            for item in self.items:
                print(f'{item["item"]} x {item["quantity"]} = ${item["price"] * item["quantity"]}')
            print('\nTotal: ${sum(item["price"] * item["quantity"] for item in self.items)}')
        else:
            print('Cannot print receipt, POS is closed.')

    def display_items(self):
        if self.state == 'open':
            for item in self.items:
                print(f'Item: {item["item"]}, Price: ${item["price"]}')
        else:
            print('Cannot display items, POS is closed.')

# 使用示例
